function freePortIfBusy(targetPort) {
  return new Promise((resolve) => {
    if (process.platform === "win32") {
      try {
        const out = execSync(`netstat -ano | findstr :${targetPort}`, { encoding: "utf8" });
        const lines = out.trim().split("\n");
        for (const line2 of lines) {
          const parts = line2.trim().split(/\s+/);
          const pid = parts[parts.length - 1];
          if (pid && pid !== String(process.pid) && pid !== "0") {
            execSync(`taskkill /F /PID ${pid}`, { stdio: "ignore" });
          }
        }
      } catch {
      }
      setTimeout(resolve, 500);
    } else {
      exec2(`fuser -k ${targetPort}/tcp 2>/dev/null || (lsof -ti:${targetPort} | xargs kill -9 2>/dev/null) || true`, () => {
        setTimeout(resolve, 800);
      });
    }
  });
}
